// One summary row per product per week, not forty listing rows.
// Google Shopping matches on TEXT, so a search for a $350 pair of headphones
// also returns cases, cables and knockoffs for $20. Taking a naive minimum
// would report a $36 "lowest price" for the Sony WH-1000XM5 and fire a price
// drop alert every single week. So the floor is trimmed against the median
// before anything is reported.
const weekOf = $now.toFormat('yyyy-MM-dd');

const median = (nums) => {
  const s = [...nums].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round(((s[m - 1] + s[m]) / 2) * 100) / 100;
};

// Anything under half the median is almost never the product you searched for.
const OUTLIER_FLOOR = 0.5;

return $input.all().map((item) => {
  const params = item.json.search_parameters || {};
  const priced = (item.json.shopping_results || []).filter(
    (o) => typeof o.extracted_price === 'number' && o.extracted_price > 0,
  );

  if (!priced.length) {
    return { json: { 'Week of': weekOf, Product: params.q || '', 'Offers compared': 0 } };
  }

  const rough = median(priced.map((o) => o.extracted_price));
  let offers = priced.filter((o) => o.extracted_price >= rough * OUTLIER_FLOOR);
  if (!offers.length) offers = priced;

  const prices = offers.map((o) => o.extracted_price);
  const cheapest = offers.reduce((a, b) => (b.extracted_price < a.extracted_price ? b : a));

  // A real discount needs a struck-through price higher than the current one.
  const discounted = offers.filter(
    (o) => typeof o.extracted_old_price === 'number' && o.extracted_old_price > o.extracted_price,
  );
  const bestCut = discounted.length
    ? Math.max(
        ...discounted.map((o) =>
          Math.round(((o.extracted_old_price - o.extracted_price) / o.extracted_old_price) * 100),
        ),
      )
    : '';

  return {
    json: {
      'Week of': weekOf,
      Product: params.q || '',
      'Lowest price': Math.min(...prices),
      'Cheapest seller': cheapest.source || '',
      'Median price': median(prices),
      'Highest price': Math.max(...prices),
      'Offers compared': offers.length,
      'Cheap outliers ignored': priced.length - offers.length,
      'Sellers discounting': discounted.length,
      'Best discount %': bestCut,
      'Cheapest listing': cheapest.product_link || '',
    },
  };
});
